    participant Null
    participant StringStream
    participant FileDescriptor

    Client->>Null: WriteTo(buf)
    Null-->>Client: size

    Client->>Null: ReadFrom(buf)
    Null-->>Client: retrieved_size

    Client->>StringStream: WriteTo(buf)
    StringStream->>read_: >> str
    StringStream->>buf: Append(str)
    StringStream-->>Client: str.length()

    Client->>StringStream: ReadFrom(buf)
    StringStream->>buf: RetrieveAllToString()
    StringStream->>write_: << str
    StringStream-->>Client: str.length()

    Client->>FileDescriptor: WriteTo(buf)
    FileDescriptor->>readv: readv(read_, bufs, 2)
    alt size < 0
