    else size <= buf_bytes.size_bytes()
        FileDescriptor->>buf: HasWritten(size)
    else
        FileDescriptor->>buf: HasWritten(buf_bytes.size_bytes())
        FileDescriptor->>buf: Append(ext_bytes.cbegin(), ext_bytes.cbegin() + (size - buf_bytes.size_bytes()))
