    FileDescriptor-->>Client: size

    Client->>FileDescriptor: ReadFrom(buf)
    FileDescriptor->>bytes: buf.ReadableBytes()
    FileDescriptor->>write: write(write_, bytes.data(), bytes.size_bytes())
